const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const blocks = item.json.blocks || [];
  const tables = blocks.filter(b => b.type === 'table');

  for (const table of tables) {
    const rows = table.rows || [];
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      const cell = (c) => {
        try {
          return (c?.elements || []).flatMap(el => (el?.elements || []).map(e => e.text || '')).join('');
        } catch { return ''; }
      };

      const call_id = cell(row[0]).trim();
      if (!call_id || seen.has(call_id)) continue;
      seen.add(call_id);

      results.push({
        json: {
          call_id,
          title: cell(row[1]).trim(),
          parties: cell(row[2]).trim(),
          sync_status: cell(row[3]).trim(),
          sync_time: cell(row[4]).trim(),
        }
      });
    }
  }
}

if (results.length === 0) {
  return [{ json: { _empty: true } }];
}
return results;

return $input.all().map((item) => {
  const r = item.json;
  const meta = Array.isArray(r.metaData) ? (r.metaData[0] || {}) : (r.metaData || {});
  const content = Array.isArray(r.content) ? (r.content[0] || {}) : (r.content || {});
  const parties = r.parties || [];
  const transcript = r.transcript || [];

  // Speaker labels use REAL names + affiliation (PII relaxation, 2026-08):
  // "Jane Doe (External)". Falls back to "Speaker N (Affiliation)" when nameless.
  const speakerLabels = {};
  parties.forEach((p, i) => {
    const affiliation = p.affiliation || 'Unknown';
    const label = (p.name || 'Speaker ' + (i + 1)) + ' (' + affiliation + ')';
    if (p.speakerId !== undefined && p.speakerId !== null) {
      speakerLabels[p.speakerId] = label;
    }
  });

  const participantLabels = parties.map((p, i) => (p.name || 'Speaker ' + (i + 1)) + ' (' + (p.affiliation || 'Unknown') + ')');

  const keyPointsText = (content.keyPoints || []).map(k => "- " + (k.text || "")).join("\n");

  const outlineText = (content.outline || []).map(s => {
    const items = (s.items || []).map(i => "  - " + (i.text || "")).join("\n");
    return "### " + (s.section || "") + "\n" + items;
  }).join("\n\n");

  const highlightsText = (content.highlights || []).map(h => {
    const items = (h.items || []).map(i => "  - " + (i.text || "")).join("\n");
    return "### " + (h.title || "") + "\n" + items;
  }).join("\n\n");

  const trackers = (content.trackers || [])
    .filter(t => Number(t.count) > 0)
    .map(t => ({ name: t.name, count: Number(t.count) }));
  const trackersText = trackers.map(t => t.name + " (" + t.count + ")").join(", ");

  const summaryParts = [
    "# " + (meta.title || "Untitled call"),
    "Date: " + r.scheduled_at,
    "Participants: " + participantLabels.join(", "),
  ];
  if (meta.url) summaryParts.push("URL: " + meta.url);
  summaryParts.push("", "## Brief", content.brief || "");
  if (keyPointsText) summaryParts.push("", "## Key Points", keyPointsText);
  if (outlineText) summaryParts.push("", "## Outline", outlineText);
  if (highlightsText) summaryParts.push("", "## Highlights", highlightsText);
  if (trackersText) summaryParts.push("", "## Trackers triggered", trackersText);
  const summaryText = summaryParts.join("\n");

  // Flat text (no timestamps) kept for the ledger content-hash only — unchanged
  // shape/behavior for anything still reading transcript_text.
  const transcriptText = transcript.map(turn => {
    const speaker = speakerLabels[turn.speakerId] || ("Speaker " + turn.speakerId);
    const sentences = (turn.sentences || []).map(s => s.text).join(" ");
    const topic = turn.topic ? " [" + turn.topic + "]" : "";
    return speaker + topic + ": " + sentences;
  }).join("\n\n");

  // Speaker-turn-grouped, TIME-ANCHORED chunks (retrieval plan §7.1/§8.2 Gong item 5).
  // Groups consecutive turns until ~1200 chars, carrying the group's start_ms
  // (first sentence of the group) / end_ms (last sentence) from Gong's
  // per-sentence start/end (ms from call start, confirmed via BigQuery schema
  // inspection 2026-08-19: transcript[].sentences[].{start,end,text}).
  // One-turn overlap between consecutive chunks, mirroring the overlap pattern
  // used elsewhere in the corpus (session/slack/plain small-to-big chunking).
  const CHUNK_TARGET_CHARS = 1200;
  const transcriptChunks = [];
  let bufLines = [];
  let bufChars = 0;
  let bufStart = null;
  let bufEnd = null;

  for (const turn of transcript) {
    const sentences = turn.sentences || [];
    if (sentences.length === 0) continue;
    const speaker = speakerLabels[turn.speakerId] || ("Speaker " + turn.speakerId);
    const topic = turn.topic ? " [" + turn.topic + "]" : "";
    const turnText = sentences.map(s => s.text).join(" ");
    const line = speaker + topic + ": " + turnText;
    const turnStart = Number(sentences[0].start);
    const turnEnd = Number(sentences[sentences.length - 1].end);

    if (bufStart === null) bufStart = turnStart;
    bufEnd = turnEnd;
    bufLines.push(line);
    bufChars += line.length;

    if (bufChars >= CHUNK_TARGET_CHARS) {
      transcriptChunks.push({ content: bufLines.join("\n\n"), start_ms: bufStart, end_ms: bufEnd });
      // 1-turn overlap: seed the next buffer with this turn
      bufLines = [line];
      bufChars = line.length;
      bufStart = turnStart;
      bufEnd = turnEnd;
    }
  }
  if (bufLines.length > 0) {
    transcriptChunks.push({ content: bufLines.join("\n\n"), start_ms: bufStart, end_ms: bufEnd });
  }

  return {
    json: {
      call_id: r.call_id,
      scheduled_at: r.scheduled_at,
      primary_user_id: r.primary_user_id || null,
      meeting_system: r.meeting_system || null,
      title: meta.title || "",
      duration: meta.duration ? Number(meta.duration) : null,
      url: meta.url || "",
      embed_url_base: `https://us-29262.app.gong.io/embedded-call?call-id=${r.call_id}`,
      summary_text: summaryText,
      transcript_text: transcriptText,
      transcript_chunks: transcriptChunks,
      parties: parties.map(p => ({ name: p.name || null, affiliation: p.affiliation || 'Unknown' })),
      trackers: trackers,
    }
  };
});

const j = $('Prepare Calls').item.json;
const out = [];

const date = j.scheduled_at ? j.scheduled_at.substring(0, 10) : null;
const shared = {
  call_id: j.call_id,
  scheduled_at: j.scheduled_at,
  date: date,
  primary_user_id: j.primary_user_id,
  meeting_system: j.meeting_system,
  title: j.title,
  url: j.url,
  embed_url_base: j.embed_url_base,
  parties: j.parties,
  trackers: j.trackers,
};

out.push({
  json: { ...shared, doc_type: "summary", content: j.summary_text, start_ms: null, end_ms: null, chunk_index: null }
});

// One item per time-anchored transcript chunk (replaces the old single flat-blob
// item — retrieval plan §7.1/§8.2 Gong item 5). Each carries start_ms/end_ms so
// search_all/get_resource_context can build from=/to= deep links per chunk.
const chunks = Array.isArray(j.transcript_chunks) ? j.transcript_chunks : [];
chunks.forEach((c, i) => {
  if (!c.content || !c.content.trim()) return;
  out.push({
    json: { ...shared, doc_type: "transcript", content: c.content, start_ms: c.start_ms, end_ms: c.end_ms, chunk_index: i }
  });
});

return out;

// DWN-65: this node is on the success output of the call node, so the
// count holds only calls that finished. Failed calls go to MarkFailed.
const count = items.length;
if (count === 0) return [];
return [{ json: { count } }];
